import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E6%8E%A7%E5%88%B6%E5%8F%B0%E8%B4%AD%E4%B9%B0%E4%B8%AD%E5%BF%83.BsNFbYRX.png",o="/assets/%E8%B4%AD%E4%B9%B0%E4%B8%AD%E5%BF%83%E8%B4%AD%E4%B9%B0%E4%B8%80%E4%B8%AA%E6%9C%8D%E5%8A%A1%E5%99%A8.B2IK0lMf.png",l="/assets/rak%E4%BA%A7%E5%93%81%E7%AE%A1%E7%90%86.D9btCBMX.png",i="/assets/%E6%88%91%E7%9A%84%E4%BA%A7%E5%93%81%E8%AF%A6%E6%83%851.Cd7a6Z5X.png",p="/assets/%E6%9F%A5%E7%9C%8B%E6%88%91%E7%9A%84%E9%92%B1%E5%8C%85.BxxCSV7f.png",g="/assets/%E6%88%91%E7%9A%84%E9%92%B1%E5%8C%85%E8%AF%A6%E6%83%85.Dj2EqYXD.png",h="/assets/%E6%88%91%E7%9A%84%E8%B4%A6%E5%8D%95%E8%AF%A6%E6%83%8511.CVraZRam.png",c="/assets/%E6%96%B0%E6%9F%A5%E7%9C%8B%E6%88%91%E7%9A%84%E5%B8%90%E5%8D%95.DKGXfNSt.png",f=JSON.parse('{"title":"控制台总览","description":"","frontmatter":{"title":"控制台总览"},"headers":[],"relativePath":"beginners-guide/console-overview/console-dashboard.md","filePath":"beginners-guide/console-overview/console-dashboard.md","lastUpdated":1794292918000}'),d={name:"beginners-guide/console-overview/console-dashboard.md"};function E(m,a,u,b,_,A){return t(),e("div",null,[...a[0]||(a[0]=[s('<p>控制台首页和分页签包含客户中心、购买中心、产品管理、技术支持和财务管理五部分信息。</p><hr><h3 id="客户中心" tabindex="-1">客户中心 <a class="header-anchor" href="#客户中心" aria-label="Permalink to &quot;客户中心&quot;">​</a></h3><p>客户中心包含账户信息、我的订单和最新信息与通知等模块。</p><h4 id="账户信息" tabindex="-1">账户信息 <a class="header-anchor" href="#账户信息" aria-label="Permalink to &quot;账户信息&quot;">​</a></h4><p>账户信息模块支持如下操作：</p><ul><li><p>支持充值操作，详细内容可参考<a href="/beginners-guide/wallet/balance.html#为-raksmart-账号充值">为 RakSmart 账号充值</a>；</p></li><li><p>支持查看<strong>余额/优惠券/代金券</strong>，详细内容可参考<a href="/beginners-guide/wallet/">钱包管理</a>；</p></li><li><p>支持查看账单信息，如未支付账单、累计消费等信息。关于账单信息的详细介绍请参考<a href="/beginners-guide/billing/">账单管理</a>；</p></li></ul><h4 id="我的订单" tabindex="-1">我的订单 <a class="header-anchor" href="#我的订单" aria-label="Permalink to &quot;我的订单&quot;">​</a></h4><p>我的订单模块支持查看当前订单、临期订单和我的服务。</p><ul><li><p><strong>当前订单</strong>：分类展示“物理服务器”、“裸机云”、“VPS” 等服务的订单数量，单击对应服务分类可查看具体订单详情；</p></li><li><p><strong>临期订单</strong>：显示“7 天内到期”、“30 天内到期”的资源数量，单击对应数字可查看即将到期的资源列表，便于及时续费。</p></li><li><p><strong>我的服务</strong>：单击<strong>我的服务</strong>可查看全部产品和服务信息，便于管理产品和服务。关于产品管理的详细介绍可参考<a href="/beginners-guide/manage-products/product-management.html">产品管理</a></p></li></ul><h4 id="最新信息与通知" tabindex="-1">最新信息与通知 <a class="header-anchor" href="#最新信息与通知" aria-label="Permalink to &quot;最新信息与通知&quot;">​</a></h4><p>最新信息与通知模块支持查看活动信息、权益提醒、最新工单和投诉封停等信息。</p><ul><li><p><strong>活动信息</strong>：查看平台最新促销活动，如当前的 YouTube 视频赚佣金活动；</p></li><li><p><strong>权益提醒</strong>：查看平台最新权益到账提醒，如优惠券到账提醒；</p></li><li><p><strong>最近工单</strong>：查看已提交工单的处理状态，如“已关闭”、“已处理”；</p></li><li><p><strong>投诉封停</strong>：查看 IP 的投诉及处理记录。</p></li></ul><hr><h3 id="购买中心" tabindex="-1">购买中心 <a class="header-anchor" href="#购买中心" aria-label="Permalink to &quot;购买中心&quot;">​</a></h3><p>在控制台内可直接选购新的产品与服务。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在左侧导航单击<strong>购买中心</strong>，进入产品和服务<strong>购物车</strong>页面。</p><p><img src="'+n+'" alt="控制台购买中心.png"></p></li><li><p>单击某个产品或服务名称，选择地区、分类等配置筛选出适合购买的服务器。关于如何购买 RakSmart 产品请参考<a href="/beginners-guide/buy-products/purchase.html">购买 RakSmart 产品</a>。</p><p><img src="'+o+'" alt="购买中心购买一个服务器.png"></p></li></ol><hr><h3 id="产品管理" tabindex="-1">产品管理 <a class="header-anchor" href="#产品管理" aria-label="Permalink to &quot;产品管理&quot;">​</a></h3><p>产品管理模块管理已购买的物理服务器、裸机云等产品。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在左侧导航<strong>产品管理</strong>区域，单击某一个产品或服务名称，进入<strong>我的产品与服务</strong>页面。</p><p><img src="'+l+'" alt="rak产品管理.png"></p></li><li><p><strong>我的产品与服务</strong>页面支持查看产品/服务详情、新开工单和查看账单信息。 <img src="'+i+'" alt="我的产品详情"></p><ul><li>查看产品/服务详情：单击<strong>产品/服务</strong>名称，即可打开该产品或服务的产品详情页面。</li><li>新开工单：单击<strong>新开工单</strong>，支持对该产品服务提交问题工单。</li><li>查看账单信息：单击<strong>账单信息</strong>，查看该产品/服务的账单记录。</li></ul></li></ol><hr><h3 id="财务管理" tabindex="-1">财务管理 <a class="header-anchor" href="#财务管理" aria-label="Permalink to &quot;财务管理&quot;">​</a></h3><p>财务管理模块支持钱包管理、账单管理。</p><h4 id="我的钱包" tabindex="-1">我的钱包 <a class="header-anchor" href="#我的钱包" aria-label="Permalink to &quot;我的钱包&quot;">​</a></h4><ol><li><p>在控制台左侧导航，单击<strong>财务管理</strong>-&gt;<strong>我的钱包</strong>，进入<strong>我的钱包</strong>页面。</p><p><img src="'+p+'" alt="查看我的钱包.png"></p></li><li><p>我的钱包支持账户余额管理、代金券管理和优惠券管理。关于我的钱包的详细介绍可参考<a href="/beginners-guide/wallet/">钱包管理</a>。</p><p><img src="'+g+'" alt="我的钱包详情.png"></p></li></ol><h4 id="我的账单" tabindex="-1">我的账单 <a class="header-anchor" href="#我的账单" aria-label="Permalink to &quot;我的账单&quot;">​</a></h4><ol><li><p>在控制台左侧导航，单击<strong>财务管理</strong>-&gt;<strong>我的账单</strong>，进入<strong>我的账单</strong>页面。</p><p><img src="'+h+'" alt="我的账单详情11.png"></p></li><li><p>我的账单支持查看不同状态的账单列表和账单管理。关于我的账单的详细介绍可参考<a href="/beginners-guide/billing/">账单管理</a>。</p><p><img src="'+c+'" alt="新查看我的帐单.png"></p></li></ol>',28)])])}const k=r(d,[["render",E]]);export{f as __pageData,k as default};
